    }

    @PostMapping("/invoices")
    public ApiResponse<InvoiceDtos.InvoiceResponse> createInvoice(
            @Valid @RequestBody InvoiceDtos.CreateInvoiceRequest request) {
        Invoice invoice = invoiceService.create(
                request.customerId(), request.amountCents(), request.note());

        InvoiceDtos.InvoiceResponse response = new InvoiceDtos.InvoiceResponse(
                invoice.id(),
                invoice.customerId(),
                invoice.amountCents(),
                invoice.note(),
                invoice.createdAt());

        return ApiResponse.ok(response);
    }
}
